<script setup lang="ts">
import { ref,computed } from 'vue'
import { get,post,request } from '../api/client'
import type { Connection,Model,Profile } from '../api/types'
import { session,allowed } from '../composables/session'
import { useQuery } from '../composables/useQuery'
import { useCursorList } from '../composables/useCursorList'
import { useMutation } from '../composables/useMutation'
import { useDirty } from '../composables/useDirty'
import PageHeader from '../components/PageHeader.vue'
import Feedback from '../components/Feedback.vue'
import ResourceTable from '../components/ResourceTable.vue'
import Modal from '../components/Modal.vue'
import Icon from '../components/Icon.vue'
import JsonView from '../components/JsonView.vue'
import StatusBadge from '../components/StatusBadge.vue'
const pid=session.project!.id,tab=ref('connections'),list=useCursorList<Connection>(`/api/v1/projects/${pid}/connections`),op=useMutation(),dirty=useDirty()
const files=useCursorList<Model<'FileAssetResponse'>>(`/api/v1/projects/${pid}/file-assets`),profiles=useCursorList<Profile>(`/api/v1/projects/${pid}/metadata-profiles`)
const opened=ref(false),editing=ref<Connection|null>(null),etag=ref<string|null>(null),name=ref(''),connector=ref<Model<'ConnectorType'>>('postgresql'),host=ref(''),port=ref('5432'),database=ref(''),schema=ref(''),environment=ref('test'),url=ref(''),bucket=ref(''),prefix=ref(''),credential=ref('none'),secretRef=ref(''),username=ref(''),password=ref(''),resources=ref(''),sample=ref(0)
const detail=ref<unknown>(null),file=ref<File|null>(null),testId=ref(''),taskId=ref('')
const test=useQuery<Model<'ConnectionTestResponse'>|null>(s=>testId.value?get(`/api/v1/connection-tests/${testId.value}`,s):Promise.resolve({data:null,etag:null,requestId:''}),[testId],4000)
const task=useQuery<Model<'ProfileTaskResponse'>|null>(s=>taskId.value?get(`/api/v1/profile-tasks/${taskId.value}`,s):Promise.resolve({data:null,etag:null,requestId:''}),[taskId],4000)
const dbEndpoint=computed(()=>!['s3','minio','rest_api'].includes(connector.value))
function reset(){editing.value=null;etag.value=null;connector.value='postgresql';port.value='5432';environment.value='test';sample.value=0;testId.value='';taskId.value='';name.value='';host.value='';database.value='';schema.value='';url.value='';bucket.value='';prefix.value='';credential.value='none';username.value='';password.value='';secretRef.value='';resources.value='';dirty.value=false;opened.value=true}
async function open(row:Record<string,unknown>){reset();const r=await op.run(()=>get<Connection>(`/api/v1/connections/${row.id}`),'');if(!r)return;editing.value=r.data;etag.value=r.etag;name.value=r.data.name;connector.value=r.data.connector_type;environment.value=r.data.environment;const e=r.data.endpoint;if(e.kind==='database'){host.value=e.host;port.value=String(e.port);database.value=e.database;schema.value=e.schema||''}else{url.value=e.base_url;if(e.kind==='object_storage'){bucket.value=e.bucket;prefix.value=e.prefix||''}}credential.value='keep'}
function close(){opened.value=false;password.value='';username.value='';dirty.value=false}
async function save(){
 const endpoint=dbEndpoint.value?{kind:'database' as const,host:host.value,port:Number(port.value),database:database.value,schema:schema.value||null}:connector.value==='rest_api'?{kind:'http' as const,base_url:url.value}:{kind:'object_storage' as const,base_url:url.value,bucket:bucket.value,prefix:prefix.value||null}
 const credentials=credential.value==='managed_ref'?{mode:'managed_ref' as const,secret_ref_id:secretRef.value}:credential.value==='inline_secret'?{mode:'inline_secret' as const,secret_values:dbEndpoint.value?{username:username.value,password:password.value}:connector.value==='rest_api'?{token:password.value}:{access_key:username.value,secret_key:password.value}}:undefined
 const payload={name:name.value.trim(),connector_type:connector.value,environment:environment.value,endpoint,...(credentials?{credentials}:{})}
 list.q.invalidate();const r=await op.run(()=>editing.value?request<Connection>(`/api/v1/connections/${editing.value.id}`,{method:'PUT',body:payload,etag:etag.value}):post<Connection>('/api/v1/connections',{...payload,project_id:pid}),'连接已保存。');password.value='';if(r){close();await list.q.refresh()}
}
async function startTest(){if(!editing.value)return;const r=await op.run(()=>post<Model<'ConnectionTestResponse'>>(`/api/v1/connections/${editing.value!.id}/tests`));if(r)testId.value=r.data.id}
async function startProfile(){if(!editing.value)return;const r=await op.run(()=>post<Model<'ProfileTaskAccepted'>>(`/api/v1/connections/${editing.value!.id}/profiles`,{resource_names:resources.value.split(/[,，\n]/).map(v=>v.trim()).filter(Boolean),sample_limit:Number(sample.value)}));if(r)taskId.value=r.data.resource_id}
async function rotate(){
 const id=editing.value?.secret_ref_id;if(!id||!window.confirm('轮换会更新所有引用此 Secret 的连接，并使旧授权绑定失效。确认使用表单中输入的新凭据？'))return
 const credentials=credential.value==='managed_ref'?{mode:'managed_ref' as const,secret_ref_id:secretRef.value}:credential.value==='inline_secret'?{mode:'inline_secret' as const,secret_values:dbEndpoint.value?{username:username.value,password:password.value}:connector.value==='rest_api'?{token:password.value}:{access_key:username.value,secret_key:password.value}}:null
 if(!credentials){op.error.value=new Error('请先选择并填写新的 Secret 引用或新凭据');return}
 const result=await op.run(async()=>{const current=await get<Model<'SecretReferenceResponse'>>(`/api/v1/secret-references/${id}`);return post<Model<'SecretReferenceResponse'>>(`/api/v1/secret-references/${id}/rotate`,{secret_ref_id:id,expected_revision:current.data.revision,credentials})},'凭据已轮换，请重新核验依赖连接及授权。');password.value='';username.value='';if(result){close();await list.q.refresh()}
}
async function upload(){if(!file.value)return;if(file.value.size>104857600){op.error.value=new Error('文件不得超过100 MiB');return}const form=new FormData();form.append('project_id',pid);form.append('file',file.value);const r=await op.run(()=>post<Model<'FileAssetResponse'>>('/api/v1/file-assets',form),'文件已受理，解析状态以服务端结果为准。');if(r){file.value=null;await files.q.refresh();await profiles.q.refresh()}}
function choose(e:Event){file.value=(e.target as HTMLInputElement).files?.[0]||null}
</script>
<template><PageHeader eyebrow="CONNECT YOUR DATA" title="数据连接与资产" description="连接异构数据源，建立可审查的元数据与文件资产。"><button v-if="tab==='connections'" class="button primary" :disabled="!allowed('create_connection')" @click="reset"><Icon name="plus" :size="16"/>新建连接</button></PageHeader><div class="tabs" role="tablist"><button v-for="t in [['connections','数据连接'],['files','文件资产'],['profiles','元数据 Profile']]" :key="t[0]" role="tab" :aria-selected="tab===t[0]" :class="{selected:tab===t[0]}" @click="tab=t[0]!">{{t[1]}}</button></div>
<Feedback :error="op.error.value" :notice="op.notice.value" :unknown="op.unknown.value"/>
<template v-if="tab==='connections'"><form class="search-box" style="margin-bottom:18px" @submit.prevent="list.apply()"><Icon name="search" :size="16"/><input v-model="list.draft.value" aria-label="搜索连接" placeholder="搜索连接名称…"/><button class="text-button">查询</button></form><Feedback :error="list.q.error.value" :loading="list.q.loading.value" @retry="list.q.refresh()"/><section class="card"><ResourceTable :rows="list.q.data.value?.items||[]" :columns="[{key:'name',label:'连接名称'},{key:'connector_type',label:'连接器'},{key:'environment',label:'环境'},{key:'updated_at',label:'最近更新',kind:'date'}]" @open="open"/><div class="pagination"><span>第 {{list.stack.value.length}} 段</span><div><button class="button small" :disabled="list.stack.value.length===1" @click="list.previous">上一段</button><button class="button small" :disabled="!list.q.data.value?.has_more" @click="list.next">下一段</button></div></div></section></template>
<template v-else-if="tab==='files'"><section class="card"><div class="card-body" style="padding-top:23px"><label class="file-drop"><Icon name="file" :size="25"/><strong>选择本地数据文件</strong><span>CSV / Excel / JSON / Parquet · 最大 100 MiB</span><input type="file" accept=".csv,.xlsx,.json,.parquet" aria-label="选择数据文件" @change="choose"/></label><div class="form-actions"><button class="button primary" :disabled="!file||!allowed('upload_file')||op.busy.value||op.unknown.value" @click="upload">上传并解析</button></div></div><Feedback :error="files.q.error.value" :loading="files.q.loading.value"/><ResourceTable :rows="files.q.data.value?.items||[]" :columns="[{key:'file_name',label:'文件名称'},{key:'file_format',label:'格式'},{key:'parse_status',label:'解析状态',kind:'status'},{key:'created_at',label:'上传时间',kind:'date'}]" @open="detail=$event"/><div class="pagination"><span>第 {{files.stack.value.length}} 段</span><div><button class="button small" :disabled="files.stack.value.length===1" @click="files.previous">上一段</button><button class="button small" :disabled="!files.q.data.value?.has_more" @click="files.next">下一段</button></div></div></section></template>
<template v-else><Feedback :error="profiles.q.error.value" :loading="profiles.q.loading.value"/><section class="card"><ResourceTable :rows="profiles.q.data.value?.items||[]" :columns="[{key:'resource_name',label:'资源名称'},{key:'profile_digest',label:'内容指纹',kind:'id'},{key:'expires_at',label:'有效期',kind:'date'}]" @open="detail=$event"/><div class="pagination"><span>第 {{profiles.stack.value.length}} 段</span><div><button class="button small" :disabled="profiles.stack.value.length===1" @click="profiles.previous">上一段</button><button class="button small" :disabled="!profiles.q.data.value?.has_more" @click="profiles.next">下一段</button></div></div></section></template>
<Modal :open="opened" :title="editing?'连接详情与维护':'新建受管连接'" :busy="op.busy.value" @close="close"><form @submit.prevent="save" @input="dirty=true"><div class="form-grid"><label class="field">连接名称<input v-model="name" name="name" required/></label><label class="field">连接器<select v-model="connector" name="connector"><option v-for="c in ['postgresql','mysql','oracle','doris','clickhouse','s3','minio','rest_api']" :key="c" :value="c">{{c}}</option></select></label><template v-if="dbEndpoint"><label class="field">主机<input v-model="host" name="host" required placeholder="数据库域名或 IP"/></label><label class="field">端口<input v-model="port" name="port" required type="number" min="1" max="65535"/></label><label class="field">数据库<input v-model="database" name="database" required/></label><label class="field">Schema（可选）<input v-model="schema" name="schema"/></label></template><template v-else><label class="field full">服务地址<input v-model="url" name="url" type="url" required placeholder="https://…"/></label><template v-if="connector!=='rest_api'"><label class="field">Bucket<input v-model="bucket" name="bucket" required/></label><label class="field">前缀（可选）<input v-model="prefix" name="prefix"/></label></template></template><label class="field">申请环境<input v-model="environment" name="environment" required/><small>由服务端校验环境与地址允许范围</small></label><label class="field">凭据方式<select v-model="credential" name="credential"><option :value="editing?'keep':'none'">{{editing?'保留已有凭据':'无凭据'}}</option><option value="managed_ref">已有 Secret 引用</option><option value="inline_secret">交由 SecretProvider 保存</option></select></label><label v-if="credential==='managed_ref'" class="field full">Secret 引用 UUID<input v-model="secretRef" name="secretRef" required/></label><template v-if="credential==='inline_secret'"><label v-if="connector!=='rest_api'" class="field">{{dbEndpoint?'用户名':'Access Key'}}<input v-model="username" name="username" required autocomplete="off"/></label><label class="field">{{dbEndpoint?'密码':connector==='rest_api'?'Token':'Secret Key'}}<input v-model="password" name="password" type="password" required autocomplete="off"/></label></template></div><Feedback :error="op.error.value" :notice="op.notice.value" :unknown="op.unknown.value"/><div class="form-actions"><button type="button" class="button" @click="close">关闭</button><button class="button primary" :disabled="!allowed(editing?'edit_connection':'create_connection')||op.busy.value||op.unknown.value">保存连接</button><button v-if="editing?.secret_ref_id" type="button" class="button danger" :disabled="!allowed('rotate_secret')||!['managed_ref','inline_secret'].includes(credential)||op.busy.value||op.unknown.value" @click="rotate">轮换共享凭据</button></div></form><template v-if="editing"><div class="block-note">连接保存、连接测试和 Profile 探查是三件独立的事。异步任务受理后，请以最终状态为准。</div><button class="button" :disabled="!allowed('test_connection')||op.busy.value" @click="startTest"><Icon name="activity" :size="15"/>只读连接测试</button><StatusBadge v-if="test.data.value" :value="test.data.value.status"/><Feedback :error="test.error.value"/><p v-if="test.data.value?.error" class="feedback error">{{test.data.value.error.message}}</p><form class="form-stack section-space" @submit.prevent="startProfile"><label class="field">探查资源名称<textarea v-model="resources" name="resources" required placeholder="表名，多项使用逗号或换行分隔"/></label><label class="field">脱敏样本上限<input v-model.number="sample" name="sample" type="number" min="0" max="100" required/></label><button class="button" :disabled="!allowed('profile_connection')||op.busy.value">发起只读探查</button><StatusBadge v-if="task.data.value" :value="task.data.value.status"/><p v-if="task.data.value?.error" class="feedback error">{{task.data.value.error.message}}</p><Feedback :error="task.error.value"/></form></template></Modal><Modal :open="detail!==null" title="安全资产详情" @close="detail=null"><JsonView :value="detail"/></Modal></template>
